/* SHIFAA front-end prototype — vanilla JavaScript SPA.
   Data starts empty. Replace API_BASE and endpoint contracts when Laravel is ready. */
const API_BASE = window.SHIFAA_API_BASE || '/api';
const state = {
  role: null,
  user: null,
  route: 'landing',
  selectedPatient: null,
  selectedReferral: null,
  selectedEncounter: null,
  patients: [], referrals: [], encounters: [], followups: [], notifications: [],
  mobileNav: false
};
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = value => (String(value || 'U').trim().split(/\s+/).slice(0,2).map(x=>x[0] || '').join('').toUpperCase());
const previewMode = new URLSearchParams(location.search).has('preview');
const icon = (name, size=18, extra='') => `<i data-lucide="${name}" class="icon ${extra}" aria-hidden="true" style="width:${size}px;height:${size}px"></i>`;
const renderIcons = (root=document) => { if (window.lucide?.createIcons) window.lucide.createIcons({root, attrs:{'stroke-width':1.85}}); };
const doctorNav = [
  {label:'Overview',icon:'layout-dashboard',route:'doctor-overview'},
  {label:'Patients',icon:'users-round',route:'doctor-patients'},
  {label:'Referrals',icon:'arrow-left-right',route:'doctor-referrals'},
  {label:'Clinical encounters',icon:'clipboard-list',route:'doctor-visits'},
  {label:'Follow-up tasks',icon:'list-checks',route:'doctor-followups'},
  {label:'Notifications',icon:'bell',route:'doctor-notifications'}
];
const patientNav = [
  {label:'My Care',icon:'house',route:'patient-care'},
  {label:'My Health File',icon:'folder-heart',route:'patient-health-file'},
  {label:'My Visits',icon:'clipboard-list',route:'patient-visits'},
  {label:'My Referrals',icon:'arrow-left-right',route:'patient-referrals'},
  {label:'My Follow-up',icon:'list-checks',route:'patient-followup'},
  {label:'My Documents',icon:'files',route:'patient-documents'},
  {label:'Notifications',icon:'bell',route:'patient-notifications'}
];
const titles = {
  'doctor-overview':'Overview','doctor-patients':'Patients','doctor-patient-profile':'Patient profile','doctor-medical-info':'Medical information','doctor-timeline':'Patient timeline','doctor-documents':'Patient documents','doctor-add-patient':'Add patient','doctor-edit-patient':'Edit patient details','doctor-credentials':'Patient credentials','doctor-referrals':'Referrals','doctor-create-referral':'Create referral','doctor-referral-detail':'Referral details','doctor-visits':'Clinical encounters','doctor-create-encounter':'Record clinical encounter','doctor-encounter-detail':'Encounter details','doctor-followups':'Follow-up tasks','doctor-notifications':'Notifications','doctor-settings':'Profile & settings','doctor-password':'Change password',
  'patient-care':'My Care','patient-health-file':'My Health File','patient-medical-info':'Medical information','patient-timeline':'Care timeline','patient-visits':'My Visits','patient-referrals':'My Referrals','patient-referral-detail':'Referral details','patient-encounter-detail':'Visit details','patient-followup':'My Follow-up','patient-documents':'My Documents','patient-document-viewer':'Document viewer','patient-notifications':'Notifications','patient-settings':'Profile & settings','patient-password':'Change password'
};
function go(route, extra={}) { Object.assign(state, extra); state.route=route; state.mobileNav=false; render(); window.scrollTo({top:0,behavior:'instant'}); }
function toast(message, type='') { const region=$('#toast-region'); if(!region)return; const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=message; region.append(el); setTimeout(()=>el.remove(),3600); }
function brand(){return `<div class="brand"><div class="brand-mark">${icon('heart-pulse',22)}</div><div><div class="brand-name">SHIFAA</div><span class="brand-sub">CARE COORDINATION</span></div></div>`;}
function navItem(item){return `<button class="nav-link ${state.route===item.route?'active':''}" data-route="${item.route}"><span class="nav-icon">${icon(item.icon,18)}</span><span>${item.label}</span>${state.route===item.route?`<span class="nav-active-indicator"></span>`:''}</button>`;}
function appShell(content){
  const isDoctor=state.role==='doctor'; const nav=isDoctor?doctorNav:patientNav; const name=state.user?.name || (isDoctor?'Doctor':'Patient');
  return `<div class="app-shell"><div class="mobile-overlay ${state.mobileNav?'show':''}" data-action="close-nav"></div>
    <aside class="sidebar ${state.mobileNav?'open':''}">${brand()}<div class="workspace-label">${isDoctor?'DOCTOR WORKSPACE':'PATIENT SPACE'}</div><nav class="nav-list">${nav.map(navItem).join('')}</nav><div class="nav-spacer"></div><div class="sidebar-bottom">${navItem({label:'Profile & settings',icon:'settings-2',route:isDoctor?'doctor-settings':'patient-settings'})}<div class="sidebar-foot">${icon('shield-check',13)} <span>PRIVATE CARE SPACE</span></div></div></aside>
    <main class="main-area"><header class="topbar"><button class="mobile-menu" data-action="toggle-nav" aria-label="Open navigation">${icon('menu',21)}</button><div class="topbar-title">${esc(titles[state.route]||'SHIFAA')}</div>${isDoctor?`<div class="topbar-search"><span class="search-symbol">${icon('search',16)}</span><input id="global-search" type="search" placeholder="Search patients or referrals" aria-label="Search patients or referrals" /></div>`:''}<button class="topbar-notification" data-route="${isDoctor?'doctor-notifications':'patient-notifications'}" aria-label="Notifications">${icon('bell',18)}</button><button class="user-menu" data-route="${isDoctor?'doctor-settings':'patient-settings'}"><span class="avatar">${initials(name)}</span><span class="user-name">${esc(name)}　${icon('chevron-down',14)}</span></button></header>${content}</main></div>`;
}
function heading(title,desc,actions=''){return `<div class="page-heading"><div><p class="eyebrow">${state.role==='doctor'?'DOCTOR WORKSPACE':'PATIENT SPACE'}</p><h1>${title}</h1>${desc?`<p class="page-description">${desc}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
function card(title,body,sub=''){return `<section class="card"><div class="panel-heading"><div><h2 class="card-title">${title}</h2>${sub?`<p class="card-subtitle">${sub}</p>`:''}</div></div><div class="panel-body">${body}</div></section>`;}
function emptyState(title,description,action='',symbol='inbox'){return `<div class="empty-state"><div class="empty-icon">${icon(symbol,22)}</div><h3>${title}</h3><p>${description}</p>${action}</div>`;}
function emptyTable(headers,message='No records to display yet.'){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody><tr><td class="table-empty" colspan="${headers.length}">${message}</td></tr></tbody></table></div>`;}
function stat(label,value,note,symbol='activity'){return `<div class="card stat-card"><div class="stat-top"><div class="stat-label">${label}</div><span class="stat-icon">${icon(symbol,19)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`;}
function field(label,name,placeholder='',type='text',opts={}){const required=opts.required?'required':''; if(type==='select'){return `<div class="field ${opts.full?'full':''}"><label for="${name}">${label}${opts.required?' *':''}</label><select id="${name}" name="${name}" ${required}><option value="">${placeholder||'Select an option'}</option>${(opts.options||[]).map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select>${opts.hint?`<span class="field-hint">${opts.hint}</span>`:''}</div>`;} if(type==='textarea'){return `<div class="field ${opts.full?'full':''}"><label for="${name}">${label}${opts.required?' *':''}</label><textarea id="${name}" name="${name}" placeholder="${placeholder}" ${required}></textarea></div>`;}return `<div class="field ${opts.full?'full':''}"><label for="${name}">${label}${opts.required?' *':''}</label><input id="${name}" name="${name}" type="${type}" placeholder="${placeholder}" ${required} ${opts.autocomplete?`autocomplete="${opts.autocomplete}"`:''}/>${opts.hint?`<span class="field-hint">${opts.hint}</span>`:''}</div>`;}
function formPage(title,desc,fields,submitLabel,action,notice=''){return `<div class="page">${heading(title,desc,`<button class="btn" data-action="back">Cancel</button>`)}<section class="card card-pad form-card">${notice?`<div class="notice" style="margin-bottom:18px">${notice}</div>`:''}<form data-form="${action}"><div class="form-grid">${fields.join('')}</div><div class="form-footer"><button type="button" class="btn" data-action="back">Cancel</button><button class="btn btn-primary" type="submit">${submitLabel}</button></div></form></section></div>`;}
function tablePage(title,desc,headers,rows,empty,actions=''){return `<div class="page">${heading(title,desc,actions)}<section class="card"><div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="table-empty">${empty}</td></tr>`}</tbody></table></div></section></div>`;}
function landing(){return `<div class="auth-layout"><aside class="auth-aside">${brand()}<div class="auth-message"><p class="eyebrow" style="color:#c7dce2">CONNECTED CARE</p><h1>Better continuity.<br/>Clearer care.</h1><p>SHIFAA brings clinical records, referrals and follow-up into one coordinated patient-care experience.</p></div><div class="auth-aside-foot">SHIFAA · CARE COORDINATION</div></aside><main class="auth-main"><div class="auth-box">${brand()}<h2>Welcome to SHIFAA</h2><p>A connected space for doctors and patients to manage care with clarity.</p><button class="btn btn-primary" data-route="signin">Sign in to your account →</button><div class="auth-bottom"><span>Secure access for authorized users</span><span>© SHIFAA</span></div>${previewMode?`<div class="notice" style="margin-top:28px">Development preview only — choose a workspace to inspect the interface.</div><div class="grid grid-2" style="margin-top:12px"><button class="btn btn-soft" data-action="preview-doctor">Preview Doctor</button><button class="btn btn-soft" data-action="preview-patient">Preview Patient</button></div>`:''}</div></main></div>`;}
function authPage(kind){const cfg={signin:{title:'Sign in',desc:'Enter the credentials provided to you to access your SHIFAA workspace.',fields:[field('Identification number','identifier','Enter your ID number','text',{required:true}),field('Password','password','Enter your password','password',{required:true})],button:'Sign in'},forgot:{title:'Recover your password',desc:'Enter your account identification number. If the account is eligible, recovery instructions will be provided through the configured secure channel.',fields:[field('Identification number','identifier','Enter your ID number','text',{required:true})],button:'Continue'},reset:{title:'Set a new password',desc:'Choose a new password for your account.',fields:[field('New password','newPassword','At least 10 characters','password',{required:true}),field('Confirm password','confirmPassword','Repeat your new password','password',{required:true})],button:'Update password'},first:{title:'Set your password',desc:'Create a private password to finish activating your patient account.',fields:[field('Identification number','identifier','Enter your ID number','text',{required:true}),field('Temporary password','temporaryPassword','Enter the password provided by your doctor','password',{required:true}),field('New password','newPassword','At least 10 characters','password',{required:true}),field('Confirm new password','confirmPassword','Repeat your new password','password',{required:true})],button:'Activate account'}}[kind];return `<div class="auth-layout"><aside class="auth-aside">${brand()}<div class="auth-message"><p class="eyebrow" style="color:#c7dce2">SHIFAA ACCESS</p><h1>Care information,<br/>connected securely.</h1><p>One sign-in. Your authorized workspace opens according to your account role.</p></div><div class="auth-aside-foot">SHIFAA · CARE COORDINATION</div></aside><main class="auth-main"><div class="auth-box"><div class="auth-brand-mobile">${brand()}</div><a class="auth-link" href="#" data-route="landing">← Back to home</a><h2 style="margin-top:24px">${cfg.title}</h2><p>${cfg.desc}</p><form data-form="auth-${kind}">${cfg.fields.join('')}<button class="btn btn-primary" type="submit">${cfg.button}</button></form><div class="auth-bottom">${kind==='signin'?`<a class="auth-link" href="#" data-route="forgot">Forgot password?</a><a class="auth-link" href="#" data-route="first-login">First patient sign-in</a>`:`<a class="auth-link" href="#" data-route="signin">Return to sign in</a>`}</div></div></main></div>`;}
function doctorOverview(){return `<div class="page">${heading('Care coordination at a glance','Referrals, clinical encounters and follow-ups in one place.',`<button class="btn btn-primary" data-route="doctor-add-patient">＋ Add patient</button>`)}<div class="grid grid-3" style="margin-bottom:19px">${stat('Registered patients',state.patients.length,'Patients in your care')}${stat('Active referrals',state.referrals.filter(r=>!['Completed','Closed'].includes(r.status)).length,'Across referral workflows')}${stat('Open follow-ups',state.followups.filter(f=>f.status!=='Completed').length,'Tasks requiring attention')}</div><div class="grid grid-2">${card('Recent referrals',emptyState('No referrals yet','Referrals you create or receive will appear here.',`<button class="btn btn-soft" data-route="doctor-create-referral">Create a referral</button>`))}${card('Follow-up tasks',emptyState('Nothing needs follow-up yet','Follow-up tasks linked to patient care will appear here.',`<button class="btn btn-soft" data-route="doctor-followups">View follow-up tasks</button>`))}${card('Recent clinical encounters',emptyState('No encounters recorded','Documented clinical visits will appear here.',`<button class="btn btn-soft" data-route="doctor-create-encounter">Record an encounter</button>`))}${card('Patient access',emptyState('Your patient list is empty','Add a patient to create their account and start coordinating care.',`<button class="btn btn-soft" data-route="doctor-add-patient">Add patient</button>`))}</div></div>`;}
function doctorPatients(){const rows=state.patients.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="small muted">${esc(p.id)}</div></td><td>${esc(p.phone||'—')}</td><td>${esc(p.updated||'—')}</td><td><span class="status info">Active</span></td><td><button class="btn btn-sm" data-action="open-patient" data-id="${esc(p.id)}">Open file</button></td></tr>`);return tablePage('Patients','Access patient accounts and their central health files.',['Patient','Contact','Last updated','Account',''],rows,'No patients have been added. Patient records will appear here after you create an account.',`<button class="btn btn-primary" data-route="doctor-add-patient">＋ Add patient</button>`);}
function addPatient(){return formPage('Add patient','Create a patient account using their identification details.',[field('Identification number','patientId','Enter national identification number','text',{required:true}),field('Full name','patientName','Patient full name','text',{required:true}),field('Date of birth','dob','','date'),field('Phone number','phone','Patient phone number','tel'),field('Email address','email','Patient email address','email'),field('Sex','sex','Select sex','select',{options:['Female','Male','Prefer not to say']}),field('Address','address','Patient address','text',{full:true}),field('Initial note','initialNote','Optional clinical or administrative note','textarea',{full:true})],'Create patient account','add-patient',`A temporary password is generated in this local preview only. In production, generate and deliver credentials through a secure server-side workflow. The patient must set a private password at first sign-in.`);}
function patientProfile(){const p=state.patients.find(x=>x.id===state.selectedPatient);return `<div class="page">${heading('Patient central file',p?`${esc(p.name)} · ${esc(p.id)}`:'Select a patient from the Patients list.',`<button class="btn" data-route="doctor-patients">Back to patients</button>${p?`<button class="btn btn-primary" data-route="doctor-edit-patient">Edit details</button>`:''}`)}${p?`<div class="detail-grid"><section class="card profile-card"><div class="profile-avatar">${initials(p.name)}</div><div><div class="profile-name">${esc(p.name)}</div><div class="profile-meta">${esc(p.id)}</div><span class="status success" style="margin-top:12px">Account active</span></div></section><div class="grid grid-2"><div class="card card-pad"><h3 class="card-title">Patient information</h3><div class="info-list" style="margin-top:12px">${[['Date of birth',p.dob],['Phone',p.phone],['Email',p.email],['Sex',p.sex],['Address',p.address]].map(([a,b])=>`<div class="info-row"><span>${a}</span><strong>${esc(b||'Not provided')}</strong></div>`).join('')}</div></div><div class="card card-pad"><h3 class="card-title">Patient file</h3><p class="card-subtitle">Navigate to the required part of the central file.</p><div class="grid" style="margin-top:15px"><button class="btn" data-route="doctor-medical-info">Medical information →</button><button class="btn" data-route="doctor-timeline">Care timeline →</button><button class="btn" data-route="doctor-documents">Documents →</button><button class="btn" data-route="doctor-visits">Clinical encounters →</button></div></div></div></div>`:emptyState('No patient selected','Choose a patient from the Patients page to open their central file.',`<button class="btn btn-primary" data-route="doctor-patients">Go to patients</button>`)}</div>`;}
function patientSubpage(kind){const p=state.patients.find(x=>x.id===state.selectedPatient);const map={medical:['Medical information','Diagnoses, allergies, medications and relevant medical history.'],timeline:['Patient timeline','A chronological view of documented care events.'],documents:['Patient documents','Documents associated with this patient file.']};const [title,desc]=map[kind];return `<div class="page">${heading(title,p?`Patient: ${esc(p.name)} · ${esc(p.id)}`:desc,`<button class="btn" data-route="doctor-patient-profile">Back to patient file</button>`)}${kind==='medical'?`<div class="grid grid-2">${card('Known conditions',emptyState('No conditions recorded','Clinical conditions will appear here when documented.'))}${card('Allergies',emptyState('No allergies recorded','Allergy information will appear here when documented.'))}${card('Current medications',emptyState('No medications recorded','Medication information will appear here when documented.'))}${card('Medical history',emptyState('No medical history recorded','Relevant history will appear here when documented.'))}</div>`:kind==='timeline'?card('Care history',emptyState('No care events yet','Documented encounters, referrals and follow-up events will appear in chronological order.')):card('Patient documents',emptyState('No documents uploaded','Documents shared with this patient will appear here.',`<button class="btn btn-soft" data-action="upload-document">Upload document</button>`))}</div>`;}
function editPatient(){const p=state.patients.find(x=>x.id===state.selectedPatient);return formPage('Edit patient details','Update the demographic and contact information for this patient.',[field('Full name','patientName',p?.name||'Patient full name','text',{required:true}),field('Date of birth','dob',p?.dob||'','date'),field('Phone number','phone',p?.phone||'','tel'),field('Email address','email',p?.email||'','email'),field('Sex','sex',p?.sex||'Select sex','select',{options:['Female','Male','Prefer not to say']}),field('Address','address',p?.address||''),''].filter(Boolean),'Save changes','edit-patient');}
function credentialsPage(){const c=state.lastCredentials;return `<div class="page">${heading('Patient credentials','Provide the generated temporary credentials to the patient securely.',`<button class="btn" data-route="doctor-patients">Back to patients</button>`)}<div class="card card-pad" style="max-width:650px">${c?`<div class="notice success">Patient account created. The patient must change the temporary password during first sign-in.</div><div class="info-list" style="margin-top:16px"><div class="info-row"><span>Patient</span><strong>${esc(c.name)}</strong></div><div class="info-row"><span>Identification number</span><strong>${esc(c.id)}</strong></div><div class="info-row"><span>Temporary password</span><strong>${esc(c.password)}</strong></div></div><div class="actions" style="margin-top:20px"><button class="btn btn-primary" data-action="copy-credentials">Copy credentials</button><button class="btn" data-route="doctor-patient-profile">Open patient file</button></div>`:emptyState('No credentials to display','Create a patient account to generate temporary credentials.')}</div></div>`;}
function doctorReferrals(){const rows=state.referrals.map(r=>`<tr><td><strong>${esc(r.id)}</strong></td><td>${esc(r.patientName)}</td><td>${esc(r.specialty)}</td><td>${esc(r.created)}</td><td><span class="status ${r.status==='Completed'?'success':'info'}">${esc(r.status)}</span></td><td><button class="btn btn-sm" data-action="open-referral" data-id="${esc(r.id)}">View</button></td></tr>`);return tablePage('Referrals','Coordinate specialist care and track referral progress.',['Referral ID','Patient','Specialty','Created','Status',''],rows,'No referrals have been created or received.',`<button class="btn btn-primary" data-route="doctor-create-referral">＋ Create referral</button>`);}
function createReferral(){return formPage('Create referral','Send a structured referral to another care provider.',[field('Patient','patientId','Select a patient','select',{required:true,options:state.patients.map(p=>`${p.id} — ${p.name}`)}),field('Receiving doctor / service','receiving','Name of receiving doctor or service','text',{required:true}),field('Specialty','specialty','Select specialty','select',{required:true,options:['Cardiology','Dermatology','Endocrinology','Neurology','Ophthalmology','Orthopedics','Other']}),field('Priority','priority','Select priority','select',{required:true,options:['Routine','Urgent']}),field('Clinical reason','reason','Reason for referral','textarea',{required:true,full:true}),field('Relevant clinical information','clinicalInfo','Relevant findings, history or context','textarea',{full:true}),field('Requested action','requestedAction','What is requested from the receiving provider?','textarea',{full:true})],'Create referral','create-referral',`SHIFAA Loop tracks the referral lifecycle. It does not search for doctors or book appointments.`);}
function referralDetail(role='doctor'){const source=role==='patient'?patientRecords(state.referrals):state.referrals;const r=source.find(x=>x.id===state.selectedReferral);return `<div class="page">${heading('Referral details',r?`${r.id} · ${esc(r.patientName)}`:'Referral information',`<button class="btn" data-route="${role==='doctor'?'doctor-referrals':'patient-referrals'}">Back to referrals</button>`)}${r?`<div class="grid grid-2"><div class="card card-pad"><h3 class="card-title">Referral summary</h3><div class="info-list" style="margin-top:12px">${[['Referral ID',r.id],['Patient',r.patientName],['Receiving doctor / service',r.receiving],['Specialty',r.specialty],['Priority',r.priority],['Created',r.created],['Status',r.status]].map(([a,b])=>`<div class="info-row"><span>${a}</span><strong>${esc(b)}</strong></div>`).join('')}</div></div><div class="card card-pad"><h3 class="card-title">Clinical context</h3><p class="small muted" style="line-height:1.7">${esc(r.reason||'No clinical reason provided.')}</p><h3 class="card-title" style="margin-top:22px">Requested action</h3><p class="small muted" style="line-height:1.7">${esc(r.requestedAction||'Not specified.')}</p></div></div><div class="card card-pad" style="margin-top:18px"><h3 class="card-title">SHIFAA Loop status</h3><p class="card-subtitle">Referral updates and responses are recorded as the care handoff progresses.</p><div class="timeline" style="margin-top:20px"><div class="timeline-item"><span class="timeline-dot"></span><div class="timeline-content"><strong>Referral created</strong><p>${esc(r.created)}</p></div></div></div>${role==='doctor'?`<div class="actions"><button class="btn btn-soft" data-action="update-referral">Update status</button></div>`:''}</div>`:emptyState('No referral selected','Choose a referral from the referrals list.')}</div>`;}
function doctorVisits(){const rows=state.encounters.map(e=>`<tr><td><strong>${esc(e.id)}</strong></td><td>${esc(e.patientName)}</td><td>${esc(e.date)}</td><td>${esc(e.type)}</td><td><span class="status success">Recorded</span></td><td><button class="btn btn-sm" data-action="open-encounter" data-id="${esc(e.id)}">View</button></td></tr>`);return tablePage('Clinical encounters','Document completed clinical visits and review previous encounter records.',['Encounter ID','Patient','Date','Visit type','Status',''],rows,'No clinical encounters have been recorded.',`<button class="btn btn-primary" data-route="doctor-create-encounter">＋ Record encounter</button>`);}
function createEncounter(){return formPage('Record clinical encounter','Document a completed patient visit. This is a clinical record, not an appointment booking.',[field('Patient','patientId','Select a patient','select',{required:true,options:state.patients.map(p=>`${p.id} — ${p.name}`)}),field('Encounter date','date','', 'date',{required:true}),field('Visit type','type','Select visit type','select',{required:true,options:['Consultation','Follow-up visit','Procedure','Other']}),field('Chief complaint','complaint','Main reason for the visit','textarea',{required:true,full:true}),field('Clinical findings','findings','Examination findings','textarea',{full:true}),field('Assessment','assessment','Clinical assessment','textarea',{required:true,full:true}),field('Plan','plan','Care plan and recommendations','textarea',{required:true,full:true}),field('Follow-up required','followup','Select','select',{options:['No','Yes']})],'Save encounter','create-encounter');}
function encounterDetail(){const e=state.encounters.find(x=>x.id===state.selectedEncounter);return `<div class="page">${heading('Encounter details',e?`${e.id} · ${esc(e.patientName)}`:'Clinical encounter',`<button class="btn" data-route="doctor-visits">Back to encounters</button>`)}${e?`<div class="grid grid-2">${card('Encounter information',`<div class="info-list">${[['Patient',e.patientName],['Date',e.date],['Visit type',e.type],['Encounter ID',e.id]].map(([a,b])=>`<div class="info-row"><span>${a}</span><strong>${esc(b)}</strong></div>`).join('')}</div>`)}${card('Chief complaint',`<p class="small muted">${esc(e.complaint)}</p>`)}${card('Clinical findings',`<p class="small muted">${esc(e.findings||'Not documented.')}</p>`)}${card('Assessment & plan',`<p class="small muted"><strong>Assessment</strong><br/>${esc(e.assessment)}</p><p class="small muted"><strong>Plan</strong><br/>${esc(e.plan)}</p>`)}</div>`:emptyState('No encounter selected','Choose an encounter from the clinical encounters list.')}</div>`;}
function followups(role='doctor'){const list=role==='doctor'?state.followups:patientRecords(state.followups).filter(f=>f.patientVisible!==false);const rows=list.map(f=>`<tr><td><strong>${esc(f.title)}</strong></td><td>${esc(f.due||'—')}</td><td><span class="status ${f.status==='Completed'?'success':'warning'}">${esc(f.status)}</span></td><td>${role==='doctor'?`<button class="btn btn-sm" data-action="complete-followup" data-id="${esc(f.id)}">${f.status==='Completed'?'Completed':'Mark complete'}</button>`:'—'}</td></tr>`);return tablePage(role==='doctor'?'Follow-up tasks':'My Follow-up',role==='doctor'?'Track actions linked to patient care.':'Review the follow-up actions shared with you.',['Task','Due date','Status',...(role==='doctor'?['Action']:[])],rows,'No follow-up tasks have been added.',role==='doctor'?`<button class="btn btn-primary" data-action="add-followup">＋ Add task</button>`:'');}
function notifications(role='doctor'){return `<div class="page">${heading('Notifications','Important updates related to care coordination and your account.')}<section class="card">${emptyState('You are all caught up','New referral updates, care handoffs and account notifications will appear here.')}</section></div>`;}
function settings(role){return `<div class="page">${heading('Profile & settings','Manage your account information and security.')}<div class="grid grid-2"><section class="card card-pad"><h2 class="card-title">Account information</h2><p class="card-subtitle">Your account is provisioned by the system administrator.</p><div class="info-list" style="margin-top:14px"><div class="info-row"><span>Account role</span><strong>${role==='doctor'?'Doctor':'Patient'}</strong></div><div class="info-row"><span>Account name</span><strong>${esc(state.user?.name||'Not available')}</strong></div><div class="info-row"><span>Identification number</span><strong>${esc(state.user?.id||'Not available')}</strong></div></div></section><section class="card card-pad"><h2 class="card-title">Security</h2><p class="card-subtitle">Keep your account secure by updating your password when needed.</p><button class="btn btn-primary" style="margin-top:18px" data-route="${role==='doctor'?'doctor-password':'patient-password'}">Change password</button></section></div><div class="actions" style="margin-top:20px"><button class="btn btn-danger" data-action="logout">Sign out</button></div></div>`;}
function changePassword(role){return formPage('Change password','Enter your current password and choose a new one.',[field('Current password','currentPassword','Current password','password',{required:true}),field('New password','newPassword','At least 10 characters','password',{required:true}),field('Confirm new password','confirmPassword','Repeat new password','password',{required:true})],'Update password','change-password');}
function currentPatientId(){return String(state.user?.id||state.user?.identifier||'').trim();}
function patientRecords(items){const id=currentPatientId();if(!id)return [];return items.filter(item=>String(item.patientId||item.patientIdentifier||item.userId||'').trim()===id);}
function patientCare(){
  const referrals=patientRecords(state.referrals), visits=patientRecords(state.encounters), tasks=patientRecords(state.followups).filter(t=>t.patientVisible!==false);
  const activeReferrals=referrals.filter(r=>!['Completed','Closed'].includes(r.status));
  const openTasks=tasks.filter(t=>t.status!=='Completed');
  const latestVisit=visits[0];
  return `<div class="page patient-page">
    <section class="patient-welcome"><div class="welcome-copy"><div class="welcome-kicker">${icon('sparkles',14)} YOUR PERSONAL CARE SPACE</div><h1>Welcome back${state.user?.name&&state.user.name!=='Patient account'?`, ${esc(state.user.name.split(' ')[0])}`:''}.</h1><p>Your health information, care updates and next steps — clearly connected in one place.</p><div class="welcome-actions"><button class="btn btn-white" data-route="patient-health-file">${icon('folder-heart',16)} Open health file</button><button class="welcome-text-link" data-route="patient-timeline">Explore care timeline ${icon('arrow-up-right',15)}</button></div></div><div class="welcome-art" aria-hidden="true"><div class="welcome-orbit orbit-one"></div><div class="welcome-orbit orbit-two"></div><div class="welcome-heart">${icon('heart-pulse',52)}</div><span class="welcome-spark spark-one"></span><span class="welcome-spark spark-two"></span></div></section>
    <div class="patient-section-head"><div><p class="eyebrow">YOUR OVERVIEW</p><h2>Care at a glance</h2><p class="section-caption">A live summary of information linked to your account.</p></div><span class="privacy-chip">${icon('shield-check',14)} Private patient space</span></div>
    <div class="grid grid-3 patient-stats">${stat('Active referrals',activeReferrals.length,activeReferrals.length?'Awaiting care updates':'No active referrals', 'arrow-left-right')}${stat('Recorded visits',visits.length,visits.length?'Documented encounters':'No visits recorded yet','clipboard-list')}${stat('Open follow-up tasks',openTasks.length,openTasks.length?'Actions shared by your care team':'No pending tasks','list-checks')}</div>
    <div class="patient-main-grid"><section class="card patient-panel"><div class="panel-heading"><div><h2 class="card-title">Your next steps</h2><p class="card-subtitle">Things shared with you by your care team.</p></div><span class="panel-heading-icon">${icon('list-checks',18)}</span></div><div class="panel-body">${openTasks.length?`<div class="patient-task-list">${openTasks.slice(0,3).map(t=>`<div class="patient-task"><span class="task-icon">${icon('circle-dot',17)}</span><div class="task-copy"><strong>${esc(t.title)}</strong><span>${t.due?`Due ${esc(t.due)}`:'No due date provided'}</span></div><span class="status warning">${esc(t.status||'Open')}</span></div>`).join('')}</div><button class="btn btn-soft patient-panel-action" data-route="patient-followup">View all follow-up tasks ${icon('arrow-right',15)}</button>`:emptyState('Nothing to do right now','When your care team shares a follow-up action, it will appear here.', '', 'list-checks')}</div></section>
    <section class="card patient-panel"><div class="panel-heading"><div><h2 class="card-title">Your latest visit</h2><p class="card-subtitle">A quick path to your documented care history.</p></div><span class="panel-heading-icon">${icon('clipboard-check',18)}</span></div><div class="panel-body">${latestVisit?`<div class="latest-visit"><span class="latest-visit-icon">${icon('stethoscope',22)}</span><div><strong>${esc(latestVisit.type||'Clinical encounter')}</strong><p>${esc(latestVisit.date||'Date not provided')}</p><span class="status success">Recorded</span></div></div><button class="btn btn-soft patient-panel-action" data-route="patient-visits">View visit history ${icon('arrow-right',15)}</button>`:emptyState('No visits recorded yet','Completed clinical visits shared with your account will appear here.', '', 'clipboard-list')}</div></section></div>
    <div class="patient-section-head patient-shortcuts-head"><div><p class="eyebrow">QUICK ACCESS</p><h2>Go to your records</h2><p class="section-caption">Open the information you need, without searching through menus.</p></div></div>
    <div class="patient-shortcuts"><button class="shortcut-card" data-route="patient-medical-info"><span class="shortcut-icon medical">${icon('heart-pulse',21)}</span><span><strong>Medical information</strong><small>Conditions, allergies and medication</small></span>${icon('chevron-right',17)}</button><button class="shortcut-card" data-route="patient-referrals"><span class="shortcut-icon referral">${icon('arrow-left-right',21)}</span><span><strong>Referral progress</strong><small>Follow your care handoffs</small></span>${icon('chevron-right',17)}</button><button class="shortcut-card" data-route="patient-documents"><span class="shortcut-icon documents">${icon('files',21)}</span><span><strong>My documents</strong><small>Reports and shared files</small></span>${icon('chevron-right',17)}</button><button class="shortcut-card" data-route="patient-timeline"><span class="shortcut-icon timeline">${icon('activity',21)}</span><span><strong>Care timeline</strong><small>Your chronological care history</small></span>${icon('chevron-right',17)}</button></div>
    <div class="patient-security-note">${icon('lock-keyhole',16)} <span><strong>Your health information is private.</strong> This space only displays information associated with your authenticated patient account.</span></div>
  </div>`;
}
function patientHealthFile(){return `<div class="page patient-page">${heading('My Health File','Your health information, shared by your care team and organized for easy access.')}<section class="health-file-intro"><div class="health-file-mark">${icon('folder-heart',28)}</div><div><strong>Your central health record</strong><p>Review the medical information, visits and documents connected to your care. Information is shown only when it has been added to your account.</p></div><span class="privacy-chip">${icon('shield-check',14)} Private</span></section><div class="patient-section-head"><div><p class="eyebrow">RECORD CATEGORIES</p><h2>Explore your health file</h2></div></div><div class="health-file-grid"><button class="health-file-card" data-route="patient-medical-info"><span class="health-file-card-icon medical">${icon('heart-pulse',23)}</span><strong>Medical information</strong><p>Conditions, allergies, medications and relevant history.</p><span class="health-file-card-link">Open section ${icon('arrow-up-right',14)}</span></button><button class="health-file-card" data-route="patient-visits"><span class="health-file-card-icon visits">${icon('clipboard-list',23)}</span><strong>Clinical visits</strong><p>Completed clinical encounters documented by your doctor.</p><span class="health-file-card-link">Open section ${icon('arrow-up-right',14)}</span></button><button class="health-file-card" data-route="patient-timeline"><span class="health-file-card-icon timeline">${icon('activity',23)}</span><strong>Care timeline</strong><p>A chronological view of your documented care events.</p><span class="health-file-card-link">Open section ${icon('arrow-up-right',14)}</span></button><button class="health-file-card" data-route="patient-documents"><span class="health-file-card-icon documents">${icon('files',23)}</span><strong>Medical documents</strong><p>Reports and files shared with your patient account.</p><span class="health-file-card-link">Open section ${icon('arrow-up-right',14)}</span></button></div><div class="patient-security-note">${icon('lock-keyhole',16)} <span>Only information shared with your account appears here. Ask your care team about records that you expect to see but cannot find.</span></div></div>`;}
function patientInfo(kind){
  const title=kind==='medical'?'Medical information':kind==='timeline'?'Care timeline':kind==='documents'?'My Documents':'My Visits';
  const visits=patientRecords(state.encounters), referrals=patientRecords(state.referrals);
  const events=[...visits.map(v=>({kind:'visit',date:v.date||'',title:v.type||'Clinical encounter',detail:v.complaint||'Clinical visit documented',route:'patient-visits'})),...referrals.map(r=>({kind:'referral',date:r.created||'',title:`Referral · ${r.specialty||'Specialist care'}`,detail:`Status: ${r.status||'Pending'}`,route:'patient-referrals'}))];
  return `<div class="page patient-page">${heading(title,kind==='medical'?'Medical details documented by your care team.':kind==='timeline'?'A chronological view of the care events shared with you.':kind==='documents'?'Documents that your care team has shared with your account.':'Your completed clinical encounters, not appointment bookings.',`<button class="btn" data-route="patient-health-file">${icon('arrow-left',15)} Back to health file</button>`)}
  ${kind==='medical'?`<div class="medical-record-grid"><section class="card medical-record-card"><div class="medical-card-heading"><span class="medical-record-icon condition">${icon('activity',19)}</span><div><h2>Known conditions</h2><p>Conditions documented in your health record.</p></div></div>${emptyState('No conditions recorded','Your care team has not added condition information yet.','','activity')}</section><section class="card medical-record-card"><div class="medical-card-heading"><span class="medical-record-icon allergy">${icon('triangle-alert',19)}</span><div><h2>Allergies</h2><p>Allergy information shared with your care team.</p></div></div>${emptyState('No allergies recorded','Your care team has not added allergy information yet.','','shield-check')}</section><section class="card medical-record-card"><div class="medical-card-heading"><span class="medical-record-icon medication">${icon('pill',19)}</span><div><h2>Medications</h2><p>Medication information documented for you.</p></div></div>${emptyState('No medications recorded','Your care team has not added medication information yet.','','pill')}</section><section class="card medical-record-card"><div class="medical-card-heading"><span class="medical-record-icon history">${icon('book-open',19)}</span><div><h2>Medical history</h2><p>Relevant history added to your health file.</p></div></div>${emptyState('No medical history recorded','Your care team has not added medical history yet.','','book-open')}</section></div>`
  :kind==='timeline'?`<section class="card patient-panel"><div class="panel-heading"><div><h2 class="card-title">Your care history</h2><p class="card-subtitle">Events are shown when they are documented and linked to your account.</p></div><span class="panel-heading-icon">${icon('activity',18)}</span></div><div class="panel-body">${events.length?`<div class="care-timeline">${events.map(ev=>`<div class="care-timeline-item"><span class="care-timeline-marker ${ev.kind}">${icon(ev.kind==='visit'?'stethoscope':'arrow-left-right',15)}</span><div class="care-timeline-content"><div class="care-timeline-meta"><strong>${esc(ev.title)}</strong><span>${esc(ev.date||'Date not provided')}</span></div><p>${esc(ev.detail)}</p></div></div>`).join('')}</div>`:emptyState('No care events yet','Clinical encounters and referral updates will appear here as your care team records them.','','activity')}</div></section>`
  :kind==='documents'?`<section class="card patient-panel"><div class="panel-heading"><div><h2 class="card-title">Documents shared with you</h2><p class="card-subtitle">Your care team’s reports and files will be available here.</p></div><span class="panel-heading-icon">${icon('files',18)}</span></div><div class="panel-body">${emptyState('No documents available','When your care team shares a document with your account, you will be able to preview it here.','','file-text')}</div></section><div class="document-guidance"><span>${icon('info',17)}</span><p><strong>Looking for a document?</strong> Documents become available after a member of your care team uploads and shares them with your patient account.</p></div>`
  :`<section class="card patient-panel"><div class="panel-heading"><div><h2 class="card-title">Completed clinical visits</h2><p class="card-subtitle">A record of visits documented by your doctor.</p></div><span class="panel-heading-icon">${icon('clipboard-list',18)}</span></div><div class="panel-body">${visits.length?`<div class="visit-list">${visits.map(v=>`<div class="visit-row"><span class="visit-icon">${icon('stethoscope',19)}</span><div class="visit-main"><strong>${esc(v.type||'Clinical encounter')}</strong><span>${esc(v.date||'Date not provided')}</span>${v.complaint?`<p>${esc(v.complaint)}</p>`:''}</div><span class="status success">Recorded</span><button class="icon-button" aria-label="View visit" data-action="open-encounter" data-id="${esc(v.id)}" data-role="patient">${icon('chevron-right',17)}</button></div>`).join('')}</div>`:emptyState('No visits recorded','Your completed clinical encounters will appear here once your doctor documents and shares them.','','clipboard-list')}</div></section>`}
  </div>`;
}
function patientReferrals(){const records=patientRecords(state.referrals);const rows=records.map(r=>`<tr><td><strong>${esc(r.id)}</strong></td><td>${esc(r.specialty)}</td><td>${esc(r.created)}</td><td><span class="status ${r.status==='Completed'?'success':'info'}">${esc(r.status)}</span></td><td><button class="btn btn-sm" data-action="open-referral" data-id="${esc(r.id)}" data-role="patient">View ${icon('arrow-up-right',13)}</button></td></tr>`);return tablePage('My Referrals','Follow the progress of referrals created by your care team.',['Referral ID','Specialty','Created','Status',''],rows,'No referrals are currently linked to your account.');}
function patientEncounterDetail(){const e=patientRecords(state.encounters).find(x=>x.id===state.selectedEncounter);return `<div class="page patient-page">${heading('Visit details',e?`${esc(e.id)} · ${esc(e.date||'Date not provided')}`:'Clinical visit',`<button class="btn" data-route="patient-visits">${icon('arrow-left',15)} Back to visits</button>`)}${e?`<div class="visit-detail-grid">${card('Visit information',`<div class="info-list">${[['Date',e.date],['Visit type',e.type],['Encounter ID',e.id]].map(([a,b])=>`<div class="info-row"><span>${a}</span><strong>${esc(b||'Not provided')}</strong></div>`).join('')}</div>`)}${card('Reason for visit',`<p class="record-prose">${esc(e.complaint||'Not documented.')}</p>`)}${card('Clinical findings',`<p class="record-prose">${esc(e.findings||'Not shared with your account.')}</p>`)}${card('Assessment and plan',`<p class="record-prose"><strong>Assessment</strong><br/>${esc(e.assessment||'Not shared with your account.')}</p><p class="record-prose"><strong>Plan</strong><br/>${esc(e.plan||'Not shared with your account.')}</p>`)}</div>`:emptyState('Visit not available','This visit is not available in your patient account.','','clipboard-list')}</div>`;}
function patientDocumentViewer(){return `<div class="page">${heading('Document viewer','View a document shared with your patient account.',`<button class="btn" data-route="patient-documents">Back to documents</button>`)}<section class="card">${emptyState('No document selected','Choose a document from My Documents to view it here.')}</section></div>`;}
function routeContent(){switch(state.route){
case'landing':return landing();case'signin':return authPage('signin');case'forgot':return authPage('forgot');case'reset-password':return authPage('reset');case'first-login':return authPage('first');
case'doctor-overview':return doctorOverview();case'doctor-patients':return doctorPatients();case'doctor-add-patient':return addPatient();case'doctor-patient-profile':return patientProfile();case'doctor-medical-info':return patientSubpage('medical');case'doctor-timeline':return patientSubpage('timeline');case'doctor-documents':return patientSubpage('documents');case'doctor-edit-patient':return editPatient();case'doctor-credentials':return credentialsPage();case'doctor-referrals':return doctorReferrals();case'doctor-create-referral':return createReferral();case'doctor-referral-detail':return referralDetail();case'doctor-visits':return doctorVisits();case'doctor-create-encounter':return createEncounter();case'doctor-encounter-detail':return encounterDetail();case'doctor-followups':return followups();case'doctor-notifications':return notifications();case'doctor-settings':return settings('doctor');case'doctor-password':return changePassword('doctor');
case'patient-care':return patientCare();case'patient-health-file':return patientHealthFile();case'patient-medical-info':return patientInfo('medical');case'patient-timeline':return patientInfo('timeline');case'patient-documents':return patientInfo('documents');case'patient-visits':return patientInfo('visits');case'patient-encounter-detail':return patientEncounterDetail();case'patient-referrals':return patientReferrals();case'patient-referral-detail':return referralDetail('patient');case'patient-followup':return followups('patient');case'patient-document-viewer':return patientDocumentViewer();case'patient-notifications':return notifications('patient');case'patient-settings':return settings('patient');case'patient-password':return changePassword('patient');default:return landing();}}
function render(){const root=$('#app');if(!root)return;const authRoutes=['landing','signin','forgot','reset-password','first-login'];if(authRoutes.includes(state.route)){root.innerHTML=routeContent();renderIcons(root);return;}root.innerHTML=appShell(routeContent());renderIcons(root);}
function setRole(role){state.role=role;state.user=state.user||{name:role==='doctor'?'Doctor account':'Patient account',id:''};go(role==='doctor'?'doctor-overview':'patient-care');}
async function api(path,options={}){const res=await fetch(`${API_BASE}${path}`,{credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const body=await res.json().catch(()=>({}));if(!res.ok)throw new Error(body.message||`Request failed (${res.status})`);return body;}
function formData(form){return Object.fromEntries(new FormData(form).entries());}
function makeId(prefix){return `${prefix}-${Date.now().toString().slice(-7)}`;}
function generateTemporaryPassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#';const bytes=new Uint32Array(14);if(window.crypto?.getRandomValues)crypto.getRandomValues(bytes);else for(let i=0;i<bytes.length;i++)bytes[i]=Math.floor(Math.random()*chars.length);return Array.from(bytes,b=>chars[b%chars.length]).join('');}
async function submitForm(form){const type=form.dataset.form;const data=formData(form);
 if(type==='auth-signin'){
   try{const result=await api('/auth/login',{method:'POST',body:JSON.stringify({identifier:data.identifier,password:data.password})});state.user=result.user;state.role=result.user.role;go(state.role==='doctor'?'doctor-overview':'patient-care');}
   catch(e){toast(e.message.includes('Failed to fetch')?'Authentication API is not connected yet. Start the Laravel backend to sign in.':e.message,'error');}return;
 }
 if(type==='auth-forgot'){try{await api('/auth/password/forgot',{method:'POST',body:JSON.stringify({identifier:data.identifier})});toast('If the account is eligible, recovery instructions will be sent securely.');}catch(e){toast(e.message,'error');}return;}
 if(type==='auth-first'){if(data.newPassword!==data.confirmPassword)return toast('The new passwords do not match.','error');if(data.newPassword.length<10)return toast('Use at least 10 characters for your password.','error');try{await api('/auth/activate',{method:'POST',body:JSON.stringify({identifier:data.identifier,temporaryPassword:data.temporaryPassword,newPassword:data.newPassword})});toast('Account activated. You can now sign in.');go('signin');}catch(e){toast(e.message,'error');}return;}
 if(type==='auth-reset'){if(data.newPassword!==data.confirmPassword)return toast('The new passwords do not match.','error');toast('Password reset requires a valid recovery token from the backend.','error');return;}
 if(type==='add-patient'){
   if(state.patients.some(p=>p.id===data.patientId))return toast('A patient with this identification number already exists.','error');
   const patient={id:data.patientId,name:data.patientName,dob:data.dob,phone:data.phone,email:data.email,sex:data.sex,address:data.address,updated:new Date().toLocaleDateString()};state.patients.push(patient);state.selectedPatient=patient.id;state.lastCredentials={...patient,password:generateTemporaryPassword()};go('doctor-credentials');return;
 }
 if(type==='edit-patient'){const p=state.patients.find(x=>x.id===state.selectedPatient);if(p)Object.assign(p,{name:data.patientName,dob:data.dob,phone:data.phone,email:data.email,sex:data.sex,address:data.address,updated:new Date().toLocaleDateString()});toast('Patient details updated in this preview.');go('doctor-patient-profile');return;}
 if(type==='create-referral'){const p=state.patients.find(x=>x.id===data.patientId.split(' — ')[0]);const referral={...data,patientId:p?.id||data.patientId.split(' — ')[0],id:makeId('REF'),patientName:p?.name||data.patientId,created:new Date().toLocaleDateString(),status:'Sent'};state.referrals.unshift(referral);state.selectedReferral=referral.id;go('doctor-referral-detail');return;}
 if(type==='create-encounter'){const p=state.patients.find(x=>x.id===data.patientId.split(' — ')[0]);const encounter={...data,patientId:p?.id||data.patientId.split(' — ')[0],id:makeId('ENC'),patientName:p?.name||data.patientId};state.encounters.unshift(encounter);state.selectedEncounter=encounter.id;go('doctor-encounter-detail');return;}
 if(type==='change-password'){if(data.newPassword!==data.confirmPassword)return toast('The new passwords do not match.','error');if(data.newPassword.length<10)return toast('Use at least 10 characters for your password.','error');try{await api('/auth/password/change',{method:'POST',body:JSON.stringify({currentPassword:data.currentPassword,newPassword:data.newPassword})});toast('Password updated.');go(state.role==='doctor'?'doctor-settings':'patient-settings');}catch(e){toast(e.message,'error');}return;}
}
function action(actionName,el){switch(actionName){case'toggle-nav':state.mobileNav=!state.mobileNav;render();break;case'close-nav':state.mobileNav=false;render();break;case'back':history.length>1?history.back():go(state.role==='doctor'?'doctor-patients':'patient-care');break;case'logout':state.role=null;state.user=null;go('landing');break;case'preview-doctor':setRole('doctor');break;case'preview-patient':setRole('patient');break;case'open-patient':state.selectedPatient=el.dataset.id;go('doctor-patient-profile');break;case'open-referral':state.selectedReferral=el.dataset.id;go(el.dataset.role==='patient'?'patient-referral-detail':'doctor-referral-detail');break;case'open-encounter':state.selectedEncounter=el.dataset.id;go(el.dataset.role==='patient'?'patient-encounter-detail':'doctor-encounter-detail');break;case'copy-credentials':if(state.lastCredentials){const c=state.lastCredentials;navigator.clipboard?.writeText(`SHIFAA patient access\nID: ${c.id}\nTemporary password: ${c.password}`).then(()=>toast('Credentials copied.')).catch(()=>toast('Clipboard access is unavailable.','error'));}break;case'complete-followup':{const f=state.followups.find(x=>x.id===el.dataset.id);if(f)f.status='Completed';toast('Task updated.');render();break;}case'add-followup':{const title=prompt('Follow-up task title');if(!title)return;const patientId=prompt(`Enter an existing patient ID (${state.patients.map(p=>p.id).join(', ')||'no patients added yet'})`);if(!patientId)return;const patient=state.patients.find(p=>p.id===patientId.trim());if(!patient)return toast('Patient ID not found. Add or select a valid patient.','error');const due=prompt('Due date (optional)')||'';state.followups.push({id:makeId('TASK'),patientId:patient.id,patientName:patient.name,title,due,status:'Open',patientVisible:true});toast('Follow-up task added for the selected patient.');render();break;}case'update-referral':{const r=state.referrals.find(x=>x.id===state.selectedReferral);if(!r)return;const status=prompt('Enter new status: Sent, Acknowledged, In progress, Completed');if(status){r.status=status;toast('Referral status updated.');render();}break;}case'upload-document':toast('Document upload will be connected to the Laravel file-storage endpoint.');break;}}
document.addEventListener('click',e=>{const route=e.target.closest('[data-route]');if(route){e.preventDefault();go(route.dataset.route);return;}const act=e.target.closest('[data-action]');if(act){action(act.dataset.action,act);return;}});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(form){e.preventDefault();submitForm(form);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.mobileNav){state.mobileNav=false;render();}});
document.addEventListener('input',e=>{if(e.target.id==='global-search'){const q=e.target.value.trim().toLowerCase();if(!q)return;const visible=state.patients.filter(p=>`${p.name} ${p.id}`.toLowerCase().includes(q));if(state.role==='doctor'&&state.route==='doctor-patients'){const body=$('.data-table tbody');if(body&&visible.length===0)body.innerHTML=`<tr><td class="table-empty" colspan="5">No matching patient found.</td></tr>`;}}});
const params=new URLSearchParams(location.search);if(params.get('preview')==='doctor')setRole('doctor');else if(params.get('preview')==='patient')setRole('patient');else render();
